MultiLanguageItemData['de'][16052] = {name = "[q2]Bauplan: Modularer Stimmenverstärker", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines modularen Stimmenverstärkers.\nBenötigt Klassische Ingenieurskunst (290)\nVerkaufspreis:\n[q2]Modularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\n[q2]Anlegen: Verringert die Wirkungsdauer jeglicher Stille- und Unterbrechungseffekte gegen den Träger um 10%. Dieser Effekt ist nicht mit anderen Effekten dieser Art stapelbar.\nVerkaufspreis: \nBenötigt Empfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal"}
MultiLanguageItemData['de'][16053] = {name = "[q2]Bauplan: Schutzbrille des Meisteringenieurs", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung einer Schutzbrille des Meisteringenieurs.\nBenötigt Klassische Ingenieurskunst (290)\nVerkaufspreis:\n[q2]Schutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n3 Rüstung\n+5 Ausdauer\n[q2]+ 7 Vielseitigkeit\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis: \nBenötigt Feuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)"}
MultiLanguageItemData['de'][16054] = {name = "[q2]Bauplan: Arkanitdrachling", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Arkanitdrachlings.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\n[q3]Arkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Benutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nBenötigt Mechanischer Mithrildrachling , Empfindlicher Arkanitwandler (4)"}
MultiLanguageItemData['de'][16055] = {name = "[q2]Bauplan: Arkane Bombe", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung einer arkanen Bombe.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nArkane Bombe\n[q2]Benutzen: Entzieht Zielen im Explosionsradius 381 Mana und fügt ihnen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen.\n\n Versagenschance erhöht, wenn Ihr über Stufe 49 seid. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nBenötigt Empfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff"}
MultiLanguageItemData['de'][16056] = {name = "[q2]Bauplan: Fehlerloses Arkanitgewehr", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines fehlerlosen Arkanitgewehrs.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\n[q3]Fehlerloses Arkanitgewehr\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n5 - 10 Schaden Geschwindigkeit 3.00\n(2.5 Schaden pro Sekunde)\n+4 Beweglichkeit\n+5 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Arkanitbarren (10), Thoriumröhre (2), Essenz des Feuers (2), Essenz der Erde (2), Azerothischer Diamant (2), Verzaubertes Leder (2)\n Optionale Reagenzien: [] (#50)"}
