MultiLanguageItemData['de'][18241] = {name = "[q4]Zaumzeug des schwarzen Schlachtrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares schwarzes Schlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dazu ausgebildet, den heftigsten Nahkampf auf den grausamsten Schlachtfeldern auszuhalten.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][18242] = {name = "[q4]Zügel des schwarzen Kriegstigers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegstiger oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wie die entfernt verwandten Nachtsäbler sind Tiger für ihre messerscharfen Klauen, ihre unglaubliche Beweglichkeit und ihre Liebe dafür, hinter den Ohren gekrault zu werden, bekannt.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][18243] = {name = "[q4]Schwarzer Schlachtenschreiter", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Schlachtenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein ordentlich beschleunigter Gnom in der Schlacht ist etwas schrecklich Schönes. - Hochtüftler Mekkadrill\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][18244] = {name = "[q4]Schwarzer Kriegswidder", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegswidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Zwerge lieben ihre Widdergefährten, weil diese sich furchtlos ins Gefecht stürzen.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
