MultiLanguageItemData['de'][22900] = {name = "Rezept: Elixier der Tarnung", additional_info = "[q2]Benutzen: Lehrt euch, wie man ein Elixier der Tarnung herstellt.\nBenötigtAlchemie der Scherbenwelt\n(5)\nVerkaufspreis:\nElixier der Tarnung\n[q2]Benutzen: Anwender kann 1 Stunde lang nicht aufgespürt werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe , Teufelsgras , Kristallphiole"}
MultiLanguageItemData['de'][22901] = {name = "Rezept: Schleichtrank", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Schleichtranks.\nBenötigtAlchemie der Scherbenwelt\n(15)\nVerkaufspreis:\nSchleichtrank\n[q2]Benutzen: Erhöht Eure Verstohlenheit 1 Min. lang um einen großen Betrag. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (2), Teufelsgras , Kristallphiole"}
MultiLanguageItemData['de'][22902] = {name = "Rezept: Elixier der erheblichen Frostmacht", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Frostmacht.\nBenötigtAlchemie der Scherbenwelt\n(20)\nVerkaufspreis:\nElixier der erheblichen Frostmacht\n[q2]Benutzen: Erhöht die Frostzaubermacht 1 Stunde lang um 18 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Wasserpartikel (2), Urflechte , Kristallphiole"}
MultiLanguageItemData['de'][22903] = {name = "[q2]Rezept: Trank der Wahnsinnsstärke", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Tranks der Wahnsinnsstärke.\nBenötigtAlchemie der Scherbenwelt\n(20)\nVerkaufspreis:\nTrank der Wahnsinnsstärke\n[q2]Benutzen: Erhöht Eure Stärke um 38 und verringert Euer Ausweichen um 24 . Hält 15 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen (3), Kristallphiole"}
MultiLanguageItemData['de'][22904] = {name = "[q2]Rezept: Elixier des suchenden Auges", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers des suchenden Auges.\nBenötigtAlchemie der Scherbenwelt\n(25)\nVerkaufspreis:\nElixier des suchenden Auges\n[q2]Benutzen: Erhöht 10 Min. lang Eure Verstohlenheitsaufdeckung. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (2), Terozapfen , Kristallphiole"}
MultiLanguageItemData['de'][22905] = {name = "Rezept: Elixier der erheblichen Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nBenötigtAlchemie der Scherbenwelt\n(30)\nBenötigtEhrenfeste\n- Wohlwollend\nVerkaufspreis: \nElixier der erheblichen Beweglichkeit\n[q2]Benutzen: Erhöht 1 Stunde lang die Beweglichkeit um 10 und den kritischen Trefferwert um 4 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Kristallphiole"}
MultiLanguageItemData['de'][22906] = {name = "[q2]Rezept: Verschleierungstrank", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Verschleierungstranks.\nBenötigtAlchemie der Scherbenwelt\n(35)\nBenötigtSporeggar\n- Ehrfürchtig\n\n\nVerschleierungstrank\n[q2]Benutzen: Verschleiert Euch gegenüber nahen Feinden, sodass Ihr weniger bedrohlich erscheint. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (3), Netherblüte , Kristallphiole"}
MultiLanguageItemData['de'][22907] = {name = "Rezept: Erstklassiger Manatrank", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines erstklassigen Manatranks.\nBenötigtAlchemie der Scherbenwelt\n(40)\nVerkaufspreis: \nErstklassiger Manatrank\n[q2]Benutzen: Stellt 682 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumwinde (2), Teufelsgras , Kristallphiole"}
MultiLanguageItemData['de'][22908] = {name = "[q2]Rezept: Elixier der erheblichen Feuermacht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Feuermacht.\nBenötigtAlchemie der Scherbenwelt\n(45)\nBenötigtDie Seher\n- Respektvoll\nVerkaufspreis: \nElixier der erheblichen Feuermacht\n[q2]Benutzen: Erhöht Eure Feuerzaubermacht 1 Stunde lang um 18 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Feuerpartikel (2), Urflechte , Kristallphiole"}
MultiLanguageItemData['de'][22909] = {name = "Rezept: Elixier der erheblichen Verteidigung", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Verteidigung.\nBenötigtAlchemie der Scherbenwelt\n(45)\nVerkaufspreis: \nElixier der erheblichen Verteidigung\n[q2]Benutzen: Erhöht die Rüstung 1 Stunde lang um 3 . Wächterelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Urflechte (3), Terozapfen , Kristallphiole"}
MultiLanguageItemData['de'][22910] = {name = "[q2]Rezept: Elixier der erheblichen Schattenmacht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Schattenmacht.\nBenötigtAlchemie der Scherbenwelt\n(50)\nBenötigtUnteres Viertel\n- Respektvoll\nVerkaufspreis:\nElixier der erheblichen Schattenmacht\n[q2]Benutzen: Erhöht die Schattenzaubermacht 1 Stunde lang um bis zu 18 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Urflechte , Alptraumranke , Kristallphiole"}
MultiLanguageItemData['de'][22911] = {name = "Rezept: Erheblicher Trank des traumlosen Schlafs", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung eines erheblichen Tranks des traumlosen Schlafs.\nBenötigtAlchemie der Scherbenwelt\n(50)\nVerkaufspreis: \nErheblicher Trank des traumlosen Schlafs\n[q2]Benutzen: Versetzt den Anwender 12 Sek. lang in einen traumlosen Schlaf. Während dieser Zeit regeneriert der Anwender ( 51 * 4) Gesundheit und ( 51 * 4) Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumwinde , Alptraumranke , Kristallphiole"}
