MultiLanguageItemData['de'][29465] = {name = "[q4]Schwarzer Schlachtenschreiter", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Schlachtenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein ordentlich beschleunigter Gnom in der Schlacht ist etwas schrecklich Schönes. - Hochtüftler Mekkadrill\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][29466] = {name = "[q4]Schwarzer Kriegskodo", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegskodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Stallmeister der Kor'kron züchten die schwarzen Kriegskodos wegen ihres aggressiven und unberechenbaren Verhaltens. Ihr Trompeten zeigt an, dass bald Blut fließen wird.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15"}
MultiLanguageItemData['de'][29467] = {name = "[q4]Schwarzer Kriegswidder", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegswidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Zwerge lieben ihre Widdergefährten, weil diese sich furchtlos ins Gefecht stürzen.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][29468] = {name = "[q4]Zaumzeug des schwarzen Schlachtrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares schwarzes Schlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dazu ausgebildet, den heftigsten Nahkampf auf den grausamsten Schlachtfeldern auszuhalten.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][29469] = {name = "[q4]Horn des schwarzen Kriegswolfs", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Werden von den Wachen von Orgrimmar wegen ihres gut ausgeprägten Geruchssinns geschätzt.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15"}
MultiLanguageItemData['de'][29470] = {name = "[q4]Rotes Skelettschlachtross", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares rotes Skelettschlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15"}
MultiLanguageItemData['de'][29471] = {name = "[q4]Zügel des schwarzen Kriegstigers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegstiger oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wie die entfernt verwandten Nachtsäbler sind Tiger für ihre messerscharfen Klauen, ihre unglaubliche Beweglichkeit und ihre Liebe dafür, hinter den Ohren gekrault zu werden, bekannt.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15"}
MultiLanguageItemData['de'][29472] = {name = "[q4]Pfeife des schwarzen Kriegsraptors", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schwarzen Kriegsraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Aus derselben brutalen Familie der Raptoren gezüchtet, die auch Ohgan gezeugt und dem Imperium der Gurubashi den Sieg gebracht hat.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15"}
