MultiLanguageItemData['de'][29713] = {name = "Muster: Trommeln der Panik", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln der Panik.\nBenötigt Lederverarbeitung der Scherbenwelt (70)\nBenötigtHüter der Zeit\n- Wohlwollend\nVerkaufspreis:\n[q2]Trommeln der Panik\n[q2]Benutzen: Unheimliche Klänge lassen 5 Feinde in einem Umkreis von 8 Metern 2 Sek. lang voller Schrecken flüchten. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Dämonenhautleder (4)"}
MultiLanguageItemData['de'][29714] = {name = "[q2]Muster: Trommeln der Wiederherstellung", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln der Wiederherstellung.\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\n[q2]Trommeln der Wiederherstellung\n[q2]Benutzen: Stellt 15 Sek. lang insgesamt 170 Gesundheit und Mana bei allen Gruppenmitgliedern in der Nähe wieder her. Unwirksam bei Zielen über Stufe 50. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppen (4)"}
MultiLanguageItemData['de'][29717] = {name = "Muster: Trommeln der Schlacht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln der Schlacht.\nBenötigt Lederverarbeitung der Scherbenwelt (65)\nBenötigtDie Sha'tar\n- Wohlwollend\nVerkaufspreis:\n[q2]Trommeln der Schlacht\n[q2]Benutzen: Erhöht das Tempo aller Gruppenmitglieder in der Nähe um bis zu 15 . Hält 30 Sek. lang an. Unwirksam bei Zielen über Stufe 50. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Dickes Grollhufleder (4)"}
MultiLanguageItemData['de'][29718] = {name = "[q2]Muster: Trommeln des Tempos", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln des Tempos.\nBenötigt Lederverarbeitung der Scherbenwelt (45)\nVerkaufspreis:\n[q2]Trommeln des Tempos\n[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit aller in der Nähe befindlichen Gruppenmitglieder um 15%. Hält 30 Sek. lang an. Kann nicht über Stufe 35 verwendet werden. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (40)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Windschuppen (4)"}
MultiLanguageItemData['de'][29719] = {name = "Muster: Kobrahautbeinrüstung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung einer Kobrahautbeinrüstung.\nBenötigt Lederverarbeitung der Scherbenwelt (35)\nBenötigtEhrenfeste\n- Wohlwollend\nVerkaufspreis: \n[q3]Kobrahautbeinrüstung\n[q2]Benutzen: Bringt dauerhaft eine Kobrahautrüstung an einer Hose an, die die Angriffskraft um 2 und den kritischen Trefferwert um 3 erhöht. Durch diese Verzauberung wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Kobraschuppen (2), Urluft (4)"}
