MultiLanguageItemData['de'][31856] = {name = "[q4]Dunkelmond-Karte: Kreuzzug", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Jedes Mal, wenn Ihr einem Gegner Nahkampf- oder Distanzschaden zufügt, wird Eure Angriffskraft 10 Sek. lang um 0 erhöht. Dieser Effekt ist bis zu 20-mal stapelbar. Jedes Mal, wenn Ihr einen Gegner mit einem Offensivzauber trefft, wird Eure Zaubermacht 10 Sek. lang um 1 erhöht. Dieser Effekt ist bis zu 10-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][31857] = {name = "[q4]Dunkelmond-Karte: Zorn", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Jedes Mal, wenn Eure direkten Schaden verursachenden Angriffe keinen kritischen Treffer erzielen, erhaltet Ihr für die nächsten 10 Sek. 3 kritischen Trefferwert und 3 kritischen Zaubertreffer. Dieser Effekt wird verbraucht, wenn Ihr einen kritischen Treffer erzielt.\nVerkaufspreis:"}
