MultiLanguageItemData['de'][32898] = {name = "Fläschchen der Stärkung aus Shattrath", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht 1 Stunde lang die maximale Gesundheit um 500 und das Ausweichen um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][32899] = {name = "Fläschchen der mächtigen Wiederherstellung aus Shattrath", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht die Vielseitigkeit 1 Stunde lang um 20 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und auf dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][32900] = {name = "Fläschchen der obersten Macht aus Shattrath", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 1 Stunde lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][32901] = {name = "Fläschchen des unerbittlichen Angriffs aus Shattrath", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht die Angriffskraft 1 Stunde lang um 19 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
