MultiLanguageItemData['de'][42985] = {name = "[q7]Zerlumpter Mantel der Furcht", additional_info = "[q7]Wird an Kriegsmeute gebunden\n{Schulter} {Stoff}\n1 Rüstung\n[q]Ornat der sagenhaften Abenteurer (0/7)\n[q0]Erbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n[q0](2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 26225 Heiligschaden zufügt und Eure <Primary Stat> 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%."}
MultiLanguageItemData['de'][42986] = {name = "Die RG-GG", additional_info = "Tausendwinter\nEinzigartig (5)\n[q2]Benutzen: Feuert eine Hitzesuchrakete ab, die versucht, feindliche Panzer zu verfolgen.\n[q2]Granatwerfer für raketengetriebene Goblingranaten werden beim Tod fallengelassen.\n[q]\"Ausschließlich für Militärzwecke.\""}
MultiLanguageItemData['de'][42987] = {name = "[q4]Dunkelmond-Karte: Grandeur", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+4 Stärke\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass 'Grandeur' ausgelöst wird. Dieser Effekt erhöht Eure Stärke, Eure Beweglichkeit oder Eure Intelligenz 15 Sek. lang um 15 . Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 45s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][42988] = {name = "[q4]Dunkelmond-Karte: Illusion", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+4 Intelligenz\n[q2]Benutzen: Absorbiert 6 Sek. lang 7 Schaden. Wenn der Schild auf irgendeine Art entfernt wird, gewinnt Ihr 77 Mana zurück. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][42989] = {name = "[q4]Dunkelmond-Karte: Berserker!", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Ihr habt eine Chance, zum Berserker zu werden, wenn Ihr im Kampf Schaden verursacht oder erleidet. Euer kritischer Trefferwert erhöht sich 12 Sek. lang um 3 . Der Effekt ist bis zu 3-mal stapelbar. (Procchance: 50%)\nVerkaufspreis:"}
