MultiLanguageItemData['de'][43656] = {name = "[q3]Foliant der Könige", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Benutzen: Erhöht Eure Werte 1 Min. lang um 3 . (10 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43657] = {name = "[q3]Königlicher Almanach der Fluchtwege", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n[q2]Benutzen: Heilt Euch um 7 . (5 Min Abklingzeit)\nVerkaufspreis:"}
