MultiLanguageItemData['de'][43659] = {name = "[q0]Blutiges Knastmesser", additional_info = "Wird beim Anlegen gebunden\n{Einhändig} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n[q]\"Das spitze Ende des Gegenstandes sieht aus, als wäre es reichlich genutzt worden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43660] = {name = "[q3]Leitfaden für Feuerschlucker", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Benutzen: Atmet Feuer auf Feinde vor Euch und verursacht 6 Feuerschaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43661] = {name = "[q3]Buch der Sterne", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Benutzen: Stellt 84 Mana wieder her. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43662] = {name = "Axt des Brandschatzers", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ihr würdet von dieser Axt erwarten, dass sie außergewöhnlich scharf ist, doch das ist sie nicht. Der Vrykul muss sich wohl eher auf seine enorme Kraft verlassen haben, um seine Gegner in Stücke zu hauen.\""}
MultiLanguageItemData['de'][43663] = {name = "[q3]Sturmgebundener Foliant", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Benutzen: Schockt einen Gegner und verursacht 7 Naturschaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43664] = {name = "[q3]Handbuch der Wolken", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+3 Ausdauer\n[q2]+ 2 Vielseitigkeit\n[q2]Benutzen: Erhöht Eure Vielseitigkeit 1 Min. lang um 16 . (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43665] = {name = "Keristraszas gebrochenes Herz", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das tragische Ende einer traurigen Geschichte. Wäre Keristrasza doch nur nicht von Malygos malträtiert und in den Wahnsinn getrieben worden.\""}
MultiLanguageItemData['de'][43666] = {name = "[q3]Höllenfeuerfoliant", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Intelligenz\nVerkaufspreis:"}
MultiLanguageItemData['de'][43667] = {name = "[q3]Buch der cleveren Tricks", additional_info = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Benutzen: Erhöht Euer Ausweichen 15 Sek. lang um 42 . (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43668] = {name = "Leylinienempfänger", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ihr seid Euch nicht so ganz sicher, was Ihr davon halten sollt. Er steckt auf jeden Fall voller arkaner Magie. Doch wie kann etwas so Kleines nur so wichtig sein?\""}
MultiLanguageItemData['de'][43669] = {name = "Medaillon der verstorbenen Königin", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die einzige Erinnerung, die König Ymiron an seine Geliebte, Königin Angerboda, hatte.\""}
MultiLanguageItemData['de'][43670] = {name = "Verzaubertes Tiki des Propheten", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Mit dem Ableben seines Trägers scheint es auch all sein Mojo verloren zu haben.\""}
MultiLanguageItemData['de'][43671] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Todesritter\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43672] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Todesritter\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43673] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Todesritter\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43674] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Druide\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43675] = {name = "[q0]Fandral Hirschhaupts Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Der Krieg der Sandstürme... Wünschte, ich könnte vergessen, dass er jemals stattgefunden hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43676] = {name = "[q0]Arkanist Doans Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Oh, wieso wollt Ihr mir einfach keine Beachtung schenken? Ich würde Euch überall hin folgen, Abbendis. Ich wünschte, Ihr würdet mich zur Kenntnis nehmen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43677] = {name = "[q0]Hochtüftler Mekkadrills Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wie kann dieser Brunnen nur funktionieren? Ich frage mich, ob ich selbst einen bauen könnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43678] = {name = "[q0]Antonidas Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Gib mir die Stärke, Dinge hinzunehmen, die ich nicht ändern kann, den Mut, Dinge zu ändern, die ich ändern kann, und die Weisheit, das eine vom anderen zu unterscheiden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43679] = {name = "[q0]Muradin Bronzebarts Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Möge uns das Heilige Licht auf unserer Expedition in den eisigen Norden beschützen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43680] = {name = "[q0]König Varian Wrynns Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, der Aufstand zuhause würde sich bald wieder legen. Würde nicht wollen, dass irgendjemand verletzt wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43681] = {name = "[q0]König Terenas Menethils Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Möge mein Sohn Arthas immer im besten Interesse seines Volkes handeln.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43682] = {name = "[q0]König Anasterian Sonnenwanderers Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich hoffe, der junge Kael'thas ist sich bewusst, dass er eines Tages unser Volk führen muss.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43683] = {name = "[q0]Khadgars Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Turalyon und Alleria, wo auch immer Ihr seid, möge es Euch wohl ergehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43684] = {name = "[q0]Medivhs Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\" \"\nVerkaufspreis:"}
