MultiLanguageItemData['de'][43686] = {name = "[q0]Allerias Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Mögen meine Schwestern ihr volles Potential erkennen; mögen ihre Taten den Namen Windläufer bekannt machen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43687] = {name = "[q0]Aegwynns Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte wirklich, dass Ihr Magier endlich damit aufhören würdet, die Köpfe in Eure eigenen... Bücher zu stecken.\"\nVerkaufspreis:"}
