MultiLanguageItemData['de'][43693] = {name = "Überrest von Akalis Mojo", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Schwer zu glauben, dass dies alles ist, was von dem einst so mächtigen Rhinozerosgott übrig geblieben ist.\""}
MultiLanguageItemData['de'][43694] = {name = "[q0]Ertrunkene Ratte", additional_info = "[q]\"Sieht so aus, als wäre das Schwimmen im Suppentopf diesmal nicht so gut gelaufen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43695] = {name = "Halbvolle Flasche Gefängnisfusel", additional_info = "[q2]Benutzen: Ein starkes alkoholisches Getränk.\n[q]\"Auch als Farblösemittel geeignet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43696] = {name = "Halbleere Flasche Gefängnisfusel", additional_info = "[q2]Benutzen: Ein starkes alkoholisches Getränk.\n[q]\"Auch als Farblösemittel geeignet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43697] = {name = "Artefakt aus der Heimatwelt der Nathrezim", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Was für eine seltsame Konstruktion. Es muss einer befremdlichsten Gegenstände sein, den Ihr je zu Gesicht bekommen habt.\""}
MultiLanguageItemData['de'][43698] = {name = "[q3]Riesige Kanalratte", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Eure riesige Kanalratte beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:"}
MultiLanguageItemData['de'][43699] = {name = "Datenscheibe: Fluch des Fleisches", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Auf diesem Ding befinden sich Informationen? Wie? Da steht gar nichts geschrieben!\""}
MultiLanguageItemData['de'][43701] = {name = "[q0]Kupfermünze eines Fußsoldaten", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wünschte, ich hätte die gleiche Aufgabe wie einer meiner Cousins: Nichts weiter tun, als unbekümmert Holz herumschleppen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43702] = {name = "[q0]Alonsus Faols Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Hoffe, dass ich eines Tages den Weg des Lichts unter dem einfachen Volke verbreiten und ihnen den Wert der Drei Tugenden näher bringen kann.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43703] = {name = "[q0]Ansirems Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Für meine Tochter wünsche ich mir Glück und Anerkennung. Sie fühlt sich hier so fehl am Platz...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43704] = {name = "[q0]Attumens Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Kann ich einen bequemeren Sattel haben? Mein Hintern tut weh.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43705] = {name = "[q0]Danaths Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Hoffe, ein Troll stirbt genau... JETZT.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43706] = {name = "[q0]Dornaas glänzende Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wünschte, dieser Trottel Arthas würde in einen Haufen Magnataurenmist fallen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43707] = {name = "[q0]Etriggs Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Möge Tirion auf seiner Suche hier in Nordend Erfolg haben oder einen ehrenhaften Tod im Kampf finden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43708] = {name = "[q0]Elling Trias' Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Schurke zu sein ist harte Arbeit. Hoffe, dass ich eines Tages meiner einzigen wahren Leidenschaft nachgehen kann...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43709] = {name = "[q0]Falstad Wildhammers Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Hoffe, dass sich die Dinge irgendwann einmal ändern werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43710] = {name = "[q0]Genns Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Pfff, die Brunnen in Gilneas könnten zehn Mal so viele Wünsche erfüllen wie die in Dalaran!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43711] = {name = "[q0]Inigos Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, mein Vater wär' wieder da...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43712] = {name = "[q0]Krasus' Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Meine Gebete gehen an meine Brüder und Schwestern, die noch immer im Herzen von Grim Batol Qualen erleiden müssen. Ich WERDE sie befreien.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43713] = {name = "[q0]Krylls Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Bumm. Bumm? Ich wünsche mir einen Bumm. Na los, mach bumm! Die Münze muss kaputt sein. Frage mich, ob sie explodieren wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43714] = {name = "[q0]Landro Fernblicks Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, ich hätte die Münze behalten...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43715] = {name = "[q0]Moloks Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Nur einmal – mehr will ich gar nicht – nur einmal möchte ich mit dem Mädchen reiten...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43716] = {name = "[q0]Murkys Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, das Wasser in Nordend wäre nicht so kalt - es macht mich müde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43717] = {name = "[q0]Prinzessin Calia Menethils Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich hoffe, dass dieser gutaussehende Edelmann Lord Prestor mich bemerkt! Was für ein Traummann!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43718] = {name = "[q0]Soldat Marcus Jonathans Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünsche mir, dass ich mir eines Tages einen prächtigen, buschigen Schnauzbart wachsen lassen werde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43719] = {name = "[q0]Salandrias Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eines Tages werde ich mächtiger sein, als all diese Magier!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43720] = {name = "[q0]Knappe Rowes Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich hoffe, dass ich irgendwann aus Sturmwind verlegt werde und Cersei wiedersehen kann. In dieser Stadt passiert nie etwas Gutes.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43721] = {name = "[q0]Stalvans Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr Magier weigert euch, mir das zu geben, was das unweigerliche Schicksal zweier sich Liebender beschleunigt, nur weil einer von beiden zu naiv ist, um es zu erkennen? Ich wünsche euch allen den Untergang.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43722] = {name = "[q0]Vereesas Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43723] = {name = "[q0]Vargoths Kupfermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, Käpt'n Sanders würde sich mit meiner Weinlieferung etwas beeilen.\"\nVerkaufspreis:"}
