MultiLanguageItemData['de'][44791] = {name = "Nobelgartenschokolade", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 24 Sek. ( 656250 / 5 * 24) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang Ausdauer und Vielseitigkeit.\nBenötigtNobelgartenfest"}
MultiLanguageItemData['de'][44792] = {name = "Blühender Zweig", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verkleidet das anvisierte Gruppenmitglied als Hase.\n5 Aufladungen"}
MultiLanguageItemData['de'][44793] = {name = "[q3]Foliant der Verwandlung: Hase", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]Benutzen: Lehrt Verwandlung: Hase.\n[q2]Verwandelt den Gegner in einen harmlosen Hasen, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]"}
MultiLanguageItemData['de'][44794] = {name = "[q2]Frühlingshasenpfote", additional_info = "[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Frühlingshasen beschwören oder wieder freigeben.\n80 ( 80)"}
