MultiLanguageItemData['de'][44811] = {name = "[q3]Foliant der Verwandlung: Truthahn", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]Benutzen: Lehrt 'Verwandlung: Truthahn'.\n[q2]Verwandelt den Gegner in einen Truthahn, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][44812] = {name = "Truthahnbüchse", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bedeckt das Ziel mit Truthahnfedern.\nBenötigtPilgerfreudenfest"}
MultiLanguageItemData['de'][44815] = {name = "Armschiene - Großer Sturmangriff", additional_info = "[q2]Benutzen: Armschienen dauerhaft verzaubern, sodass die Angriffskraft um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][44817] = {name = "[q2]Der Unruhestifter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwandelt ein befreundetes Ziel in ein Schaf und zwingt es, 15 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren und ausschließlich in Dalaran.\nVerkaufspreis:"}
