MultiLanguageItemData['de'][44934] = {name = "[q4]Fingerreif der Kirin Tor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Intelligenz\n+3 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Benutzen: Teleportiert den Zaubernden nach Dalaran. (30 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][44935] = {name = "[q4]Ring der Kirin Tor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Benutzen: Teleportiert den Zaubernden nach Dalaran. (30 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][44936] = {name = "[q3]Titanbeschlag", additional_info = "[q2]Benutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an, der das Parieren um 3 erhöht und die Dauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\n\n Durch das Anbringen des Titanbeschlags wird Euer Schild seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][44937] = {name = "[q3]Pläne: Titanbeschlag", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Titanbeschlags.\nBenötigt Schmiedekunst von Nordend (75)\nBenötigtVorhut der Allianz\n- Ehrfürchtig\n\n\n[q3]Titanbeschlag\n[q2]Benutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an, der das Parieren um 3 erhöht und die Dauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\n\n Durch das Anbringen des Titanbeschlags wird Euer Schild seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Titanbarren (4), Äonenschatten (4)"}
