MultiLanguageItemData['de'][45589] = {name = "[q4]Roboschreiter aus Gnomeregan", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Roboschreiter aus Gnomeregan oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn Ihr definitiv, unbedingt sofort dort sein müsst. - Rillie Spindelnuss\"\nVerkäufer:\nRillie Spindelnuss\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45590] = {name = "[q4]Elekk aus der Exodar", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Elekk aus der Exodar oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Elekks aus der Exodar erhielten den Segen von O'ros, dem Naaru, der mit Velen und seinen Gefolgsleuten von Draenor nach Azeroth gezogen ist.\"\nVerkäufer:\nIrisee\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45591] = {name = "[q4]Darnassischer Nachtsäbler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren darnassischen Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn das Reittier eines Nachtelfen stirbt, behält dessen Reiter traditionell einen seiner großen Fangzähne als Erinnerungsstück.\"\nVerkäufer:\nRook Falkenfaust\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45592] = {name = "[q4]Kodo aus Donnerfels", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Kodo aus Donnerfels oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als Alpha seiner Herde ist dieser Kodo ein Paradebeispiel für diese mächtigen Kreaturen, die durch Mulgore donnern.\"\nVerkäufer:\nDoru Donnerhorn\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45593] = {name = "[q4]Raptor der Dunkelspeere", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Raptor der Dunkelspeere oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Raptorenart wurde ursprünglich von den Drakkari gezüchtet, doch ist mittlerweile vom Dunkelspeerstamm in Nordend übernommen worden.\"\nVerkäufer:\nSamamba\nZone:\nEiskrone\nKosten:\n100"}
