MultiLanguageItemData['de'][45595] = {name = "[q4]Wolf aus Orgrimmar", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Worg aus Orgrimmar oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Kurze Zeit lang ließen viele Orcs verlauten, dass sie \"hungrig wie ein Wolf aus Orgrimmar\" wären. Einige Blutelfen nutzen den Spruch noch immer voller Ironie.\"\nVerkäufer:\nFreka Blutaxt\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45596] = {name = "[q4]Falkenschreiter aus Silbermond", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Falkenschreiter aus Silbermond oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ich sag nur, ich hätte heute Lust auf Hühnchen. Plötzlich liege ich mit dem Rücken auf dem Boden und das Viech versucht herauszufinden, wie meine Augen schmecken. - Stümpi Sprengbolz\"\nVerkäufer:\nTrellis Morgensonne\nZone:\nEiskrone\nKosten:\n100"}
MultiLanguageItemData['de'][45597] = {name = "[q4]Schlachtross der Verlassenen", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares Schlachtross der Verlassenen oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nEliza Killian\nZone:\nEiskrone\nKosten:\n100"}
