MultiLanguageItemData['de'][46710] = {name = "Rezept: Totenspeise", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man Totenspeise backt.\nBenötigt Klassische Kochkunst (1)\nBenötigtTag der Toten\nVerkaufspreis:\nTotenspeise\n[q2]Benutzen: Stellt im Verlauf von 25 Sek. ( 630000 / 5 * 25) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nBenötigtTag der Toten\nVerkaufspreis:\nBenötigt Herkömmliches Mehl , Eiskalte Milch"}
MultiLanguageItemData['de'][46711] = {name = "Seelenkerze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert eine Seelenkerze, welche die Willenskraft aller in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nBenötigtTag der Toten\nVerkaufspreis:"}
MultiLanguageItemData['de'][46714] = {name = "Halgas 'Straßenfeger'", additional_info = "Questgegenstand\n[q]\"Die Läufe dieser monströsen Waffe sind fast so dick wie Eure Faust. Sie kann nur von einem Karawanenkodo aus angewendet werden.\""}
MultiLanguageItemData['de'][46715] = {name = "Geheiligte Mondsteine", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Der Glanz von Elunes Anmut scheint durch.\""}
MultiLanguageItemData['de'][46716] = {name = "Zornwurzelsamen", additional_info = "Questgegenstand\n[q2]Benutzen: Lässt Wurzeln das Ziel würgen, bis es tot ist. Wirkt nur bei Teufelsfelsgrellkin."}
MultiLanguageItemData['de'][46718] = {name = "Orangefarbene Ringelblumen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Gewährt 30 Sek. lang Entdeckung geringer Unsichtbarkeit. Wirkt nur am Tag der Toten. (30 Sek. Abklingzeit)\nBenötigtTag der Toten\n[q]\"Zieht angeblich Geister an und hilft dabei, am Tag der Toten mit den Seelen der Verstorbenen zu kommunizieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][46720] = {name = "Shael'dryns Totstelltechnik", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Stellt sich tot, wodurch andere erfolgreich verwirrt werden können. Hält 6 Min. lang an. Funktioniert nur im Schattenwinkel. (2 Sek., 500 Ms Abklingzeit)"}
