MultiLanguageItemData['de'][46743] = {name = "[q4]Schneller purpurfarbener Raptor", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schnellen purpurfarbenen Raptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Diese Dschungeljäger sind schon lange mit den Trollen verbündet und haben eine enge Bindung zu ihren Herren aufgebaut. Sie sind zum Reittier, Beschützer und Freund geworden.\"\nVerkäufer:\nSamamba\nZone:\nEiskrone\nKosten:"}
MultiLanguageItemData['de'][46744] = {name = "[q4]Schneller Mondsäbler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schnellen Mondsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Viele Nachtelfen verehren diese stolzen Reittiere, da deren schimmernde Felle für sie Elune, die Göttin des Mondes, symbolisieren.\"\nVerkäufer:\nRook Falkenfaust\nZone:\nEiskrone\nKosten:"}
MultiLanguageItemData['de'][46745] = {name = "[q4]Großer roter Elekk", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren großen roten Elekk oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die ersten roten Elekkkälber wurden in Azeroth nach der Ankunft der Exodar geboren und wurden nie in Nagrand gesichtet. Einige Züchter sind der Ansicht, dass die einzigartige Färbung derselben Strahlung entspringt, die auch die Blutmythosinsel verwüstet hat.\"\nVerkäufer:\nIrisee\nZone:\nEiskrone\nKosten:"}
MultiLanguageItemData['de'][46746] = {name = "[q4]Weißes Skelettschlachtross", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein weißes Skelettschlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nEliza Killian\nZone:\nEiskrone\nKosten:"}
MultiLanguageItemData['de'][46747] = {name = "[q4]Turboschreiter", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Turboschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der Spiegel ist nicht dazu da, damit Ihr zurückblicken könnt, sondern damit Eure Feinde noch etwas anderes als Euren Auspuff zu sehen bekommen. - Rillie Spindelnuss\"\nVerkäufer:\nRillie Spindelnuss\nZone:\nEiskrone\nKosten:"}
MultiLanguageItemData['de'][46748] = {name = "[q4]Schneller violetter Widder", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schnellen violetten Widder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der dicke Schädel und die riesigen Hörner des Barak-Tor'ol-Widders machen ihn zum perfekten Reittier, um durch Gruppen gepanzerter Gegner zu rasen.\"\nVerkäufer:\nDerrick Scheckenbart\nZone:\nEiskrone\nKosten:"}
