MultiLanguageItemData['de'][46803] = {name = "Rezept: Gewürzbrotfüllung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\nBenötigt Klassische Kochkunst (1)\n\n\nGewürzbrotfüllung\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Ausdauer.\nBenötigtPilgerfreudenfest\nVerkaufspreis:\nBenötigt Gewürzbrot , Herbstliche Gewürze"}
MultiLanguageItemData['de'][46804] = {name = "Rezept: Kürbiskuchen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man Kürbiskuchen zubereitet.\nBenötigt Klassische Kochkunst (100)\n\n\nKürbiskuchen\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang kritischen Trefferwert.\nBenötigtPilgerfreudenfest\nVerkaufspreis:\nBenötigt Reifer Tirisfalkürbis , Honig"}
MultiLanguageItemData['de'][46805] = {name = "Rezept: Moosbeerenchutney", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\nBenötigt Klassische Kochkunst (160)\n\n\nMoosbeerenchutney\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Vielseitigkeit.\nBenötigtPilgerfreudenfest\nVerkaufspreis:\nBenötigt Säuerliche Moosbeeren vom Südstrom , Honig"}
MultiLanguageItemData['de'][46806] = {name = "Rezept: Kandierte Süßkartoffel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\nBenötigt Klassische Kochkunst (220)\n\n\nKandierte Süßkartoffel\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Tempo.\nBenötigtPilgerfreudenfest\nVerkaufspreis:\nBenötigt Süßkartoffel aus Mulgore , Honig , Herbstliche Gewürze"}
