MultiLanguageItemData['de'][48110] = {name = "Vortexstein", additional_info = "Questgegenstand\n[q2]Benutzen: Beschwört einen hauchdünnen Vortex, der wächst, wenn Jüngerinnen von Elune in seiner Nähe getötet werden. (3 Sek. Abklingzeit)"}
